#[test]
fn parse_config_errors_on_non_mapping_content() {
    // A YAML scalar is not a valid config — should error, not silently default
    let result = parse_config("just a string", Path::new("test.yml"));
    assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));

    // A YAML sequence is not a valid config
    let result = parse_config("- item1\n- item2", Path::new("test.yml"));
    assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));

    // A YAML boolean is not a valid config
    let result = parse_config("true", Path::new("test.yml"));
    assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));

    // A YAML number is not a valid config
    let result = parse_config("42", Path::new("test.yml"));
    assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));
}

#[test]
fn load_config_value_errors_on_non_mapping_content() {
    let temp = TempDir::new().unwrap();

    // A file with a YAML scalar should error
    let path = temp.path().join("scalar.yml");
    fs::write(&path, "just a string value").unwrap();
    let result = load_config_value(&path);
    assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));

    // A file with a YAML sequence should error
    let path = temp.path().join("seq.yml");
    fs::write(&path, "- item1\n- item2").unwrap();
    let result = load_config_value(&path);
    assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));
}

#[test]
fn load_config_value_returns_empty_mapping_for_empty_file() {
    let temp = TempDir::new().unwrap();
    let path = temp.path().join("empty.yml");
    fs::write(&path, "").unwrap();

    let value = load_config_value(&path).unwrap();
    assert!(value.as_mapping().is_some());
    assert!(value.as_mapping().unwrap().is_empty());
}

#[test]
fn load_config_value_returns_empty_mapping_for_comment_only_file() {
    let temp = TempDir::new().unwrap();
    let path = temp.path().join("comments.yml");
    fs::write(&path, "# just a comment\n# another comment\n").unwrap();

    let value = load_config_value(&path).unwrap();
    assert!(value.as_mapping().is_some());
    assert!(value.as_mapping().unwrap().is_empty());
}

#[test]
fn load_merged_config_warns_on_invalid_project_config() {
    // A project config with non-mapping YAML should produce a parse error
    let temp = TempDir::new().unwrap();
    let bivvy_dir = temp.path().join(".bivvy");
    fs::create_dir_all(&bivvy_dir).unwrap();
    fs::write(bivvy_dir.join("config.yml"), "- not\n- a\n- mapping").unwrap();

    let result = load_merged_config(temp.path());
    assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));
}

