/// Load a config file as raw YAML Value (for merging).
///
/// Returns the raw serde_yaml::Value without deserializing into
/// BivvyConfig, which allows for deep merging before final parsing.
///
/// Empty or comment-only files produce an empty mapping (not null),
/// preventing them from nuking accumulated values during merge.
/// Files whose content parses as a non-mapping value (scalar, sequence)
/// are rejected with a parse error rather than silently producing
/// unexpected merge behavior.
pub fn load_config_value(path: &Path) -> Result<serde_yaml::Value> {
    let content = fs::read_to_string(path).map_err(|e| {
        if e.kind() == std::io::ErrorKind::NotFound {
            BivvyError::ConfigNotFound {
                path: path.to_path_buf(),
            }
        } else {
            BivvyError::Io(e)
        }
    })?;

    let value: serde_yaml::Value =
        serde_yaml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
            path: path.to_path_buf(),
            message: e.to_string(),
        })?;

    match &value {
        serde_yaml::Value::Mapping(_) => Ok(value),
        serde_yaml::Value::Null => Ok(serde_yaml::Value::Mapping(Default::default())),
        _ => Err(BivvyError::ConfigParseError {
            path: path.to_path_buf(),
            message: format!(
                "expected a YAML mapping but found {}; the file may be invalid",
                yaml_type_name(&value)
            ),
        }),
    }
}

fn yaml_type_name(value: &serde_yaml::Value) -> &'static str {
    match value {
        serde_yaml::Value::Null => "null",
        serde_yaml::Value::Bool(_) => "a boolean",
        serde_yaml::Value::Number(_) => "a number",
        serde_yaml::Value::String(_) => "a string",
        serde_yaml::Value::Sequence(_) => "a sequence",
        serde_yaml::Value::Mapping(_) => "a mapping",
        serde_yaml::Value::Tagged(_) => "a tagged value",
    }
}

