//! Configuration file discovery and loading.
//!
//! This module handles finding and loading configuration files from
//! various locations in the correct priority order.

use crate::config::discovery::Discovery;
use crate::config::extends::ExtendsResolver;
use crate::config::merger::merge_configs;
use crate::config::schema::{BivvyConfig, StepConfig, WorkflowConfig, WorkflowFile};
use crate::config::trust::{TrustPolicy, TrustStore};
use crate::error::{BivvyError, Result};
use crate::ui::{Prompt, PromptResult, PromptType, Prompter};
use std::fs;
use std::path::{Path, PathBuf};

/// Selects which workflow files participate in a merge.
///
/// `bivvy run` only merges the named workflow file, while `bivvy config
/// --merged` (and the legacy `load_merged_config` entry point) merge all
/// of them.
#[derive(Debug, Clone)]
#[allow(dead_code)]
enum WorkflowSelection<'a> {
    /// Include every workflow file under `.bivvy/workflows/`.
    All,
    /// Include only the workflow file matching the given filename stem.
    One(&'a str),
    /// Include no workflow files (used by per-target lint paths).
    None,
}

/// Paths to configuration files in priority order (later overrides earlier).
///
/// Merge order:
/// 1. Remote base configs (from `extends:`)
/// 2. User global config (`~/.bivvy/config.yml`)
/// 3. Project config (`.bivvy/config.yml`)
/// 4. Split-file steps (`.bivvy/steps/*.yml`)
/// 5. Split-file workflows (`.bivvy/workflows/*.yml`)
/// 6. Local overrides (`.bivvy/config.local.yml`)
#[derive(Debug, Clone)]
pub struct ConfigPaths {
    /// Remote base config (if extends: is used)
    pub extends: Vec<PathBuf>,

    /// User's global config: ~/.bivvy/config.yml
    pub user_global: Option<PathBuf>,

    /// Project config: .bivvy/config.yml
    pub project: Option<PathBuf>,

    /// Split-file step definitions: .bivvy/steps/*.yml
    pub split_steps: Vec<PathBuf>,

    /// Split-file workflow definitions: .bivvy/workflows/*.yml
    pub split_workflows: Vec<PathBuf>,

    /// Local overrides: .bivvy/config.local.yml
    pub project_local: Option<PathBuf>,
}

impl ConfigPaths {
    /// Discover config files for the given project root.
    pub fn discover(project_root: &Path) -> Self {
        Self {
            extends: Vec::new(), // Populated later after parsing project config
            user_global: Self::find_user_global(),
            project: Self::find_project_config(project_root),
            split_steps: Self::find_split_files(project_root, "steps"),
            split_workflows: Self::find_split_files(project_root, "workflows"),
            project_local: Self::find_project_local(project_root),
        }
    }

    /// Find user's global config at ~/.bivvy/config.yml
    fn find_user_global() -> Option<PathBuf> {
        let path = crate::sys::home_dir()?.join(".bivvy").join("config.yml");
        if path.exists() {
            Some(path)
        } else {
            None
        }
    }

    /// Find project config at .bivvy/config.yml
    fn find_project_config(project_root: &Path) -> Option<PathBuf> {
        let path = project_root.join(".bivvy").join("config.yml");
        if path.exists() {
            Some(path)
        } else {
            None
        }
    }

    /// Find local overrides at .bivvy/config.local.yml
    fn find_project_local(project_root: &Path) -> Option<PathBuf> {
        let path = project_root.join(".bivvy").join("config.local.yml");
        if path.exists() {
            Some(path)
        } else {
            None
        }
    }

    /// Find YAML files in `.bivvy/<subdir>/`.
    ///
    /// Returns sorted paths for deterministic merge order.
    fn find_split_files(project_root: &Path, subdir: &str) -> Vec<PathBuf> {
        let dir = project_root.join(".bivvy").join(subdir);
        if !dir.is_dir() {
            return Vec::new();
        }

        let mut files: Vec<PathBuf> = fs::read_dir(&dir)
            .into_iter()
            .flatten()
            .filter_map(|entry| entry.ok())
            .map(|entry| entry.path())
            .filter(|path| {
                path.extension()
                    .is_some_and(|ext| ext == "yml" || ext == "yaml")
            })
            .collect();

        files.sort();
        files
    }

    /// Returns all existing config paths in merge order (excludes split files).
    pub fn all_existing(&self) -> Vec<&PathBuf> {
        let mut paths = Vec::new();

        for p in &self.extends {
            paths.push(p);
        }

        if let Some(p) = &self.user_global {
            paths.push(p);
        }

        if let Some(p) = &self.project {
            paths.push(p);
        }

        if let Some(p) = &self.project_local {
            paths.push(p);
        }

        paths
    }

    /// Check if any project config exists.
    ///
    /// Returns true if `.bivvy/config.yml` exists OR if any split-file
    /// steps/workflows are present.
    pub fn has_project_config(&self) -> bool {
        self.project.is_some() || !self.split_steps.is_empty() || !self.split_workflows.is_empty()
    }

    /// Whether any split files were discovered.
    pub fn has_split_files(&self) -> bool {
        !self.split_steps.is_empty() || !self.split_workflows.is_empty()
    }
}

/// Ensure the global config directory, config file, and schema exist.
///
/// Creates `~/.bivvy/config.yml` (with commented-out examples) and
/// `~/.bivvy/schema.json` if they don't already exist. Called on every
/// invocation so every install path (Homebrew, `cargo install`,
/// `install.sh`) gets the global config without relying on the installer.
///
/// The schema file is always rewritten so it stays current after upgrades.
///
/// Failures are silently ignored — a missing global config is not fatal.
pub fn ensure_global_config() {
    let Some(home) = crate::sys::home_dir() else {
        return;
    };
    ensure_global_config_in(home);
}

/// Inner implementation that accepts an explicit home directory.
///
/// Separated from [`ensure_global_config`] so tests can point at a temp dir.
fn ensure_global_config_in(home: PathBuf) {
    let bivvy_dir = home.join(".bivvy");

    if fs::create_dir_all(&bivvy_dir).is_err() {
        return;
    }

    // Write schema.json on every run so it stays current after upgrades.
    let schema_path = bivvy_dir.join("schema.json");
    let _ = fs::write(&schema_path, crate::lint::schema_json());

    // Only create config.yml if it doesn't exist yet.
    let config_path = bivvy_dir.join("config.yml");
    if !config_path.exists() {
        let schema_display = schema_path.display();
        let content = format!(
            "\
# yaml-language-server: $schema={schema_display}
#
# Bivvy global configuration
# Docs: https://bivvy.dev/configuration
#
# Settings here apply to ALL projects on this machine.
# Project-level .bivvy/config.yml overrides these defaults.

# settings:
#   defaults:
#     output: verbose        # verbose | quiet | silent
#     auto_run: true         # auto-run steps or prompt first
#     prompt_on_rerun: false # prompt before re-running completed steps
#   parallel: false          # enable parallel step execution
#   max_parallel: 4          # max concurrent steps (when parallel: true)
#   auto_update: true        # check for bivvy updates in the background
#   logging: false           # enable JSONL event logging
"
        );

        let _ = fs::write(&config_path, content);
    }
}

/// Find the project root by walking up from current directory.
///
/// Looks for:
/// 1. `.bivvy` directory (primary indicator)
/// 2. `.git` directory (fallback)
///
/// # Returns
///
/// The path to the project root, or None if not found.
pub fn find_project_root(start: &Path) -> Option<PathBuf> {
    let mut current = start.to_path_buf();

    loop {
        // Check for .bivvy directory
        if current.join(".bivvy").is_dir() {
            return Some(current);
        }

        // Check for .git directory (fallback)
        if current.join(".git").exists() {
            return Some(current);
        }

        // Move up one directory
        if !current.pop() {
            return None;
        }
    }
}

/// Load a single config file and parse it into BivvyConfig.
///
/// # Errors
///
/// Returns `ConfigNotFound` if the file doesn't exist.
/// Returns `ConfigParseError` if the YAML is invalid.
pub fn load_config_file(path: &Path) -> Result<BivvyConfig> {
    let content = fs::read_to_string(path).map_err(|e| {
        if e.kind() == std::io::ErrorKind::NotFound {
            BivvyError::ConfigNotFound {
                path: path.to_path_buf(),
            }
        } else {
            BivvyError::Io(e)
        }
    })?;

    parse_config(&content, path)
}

/// Parse YAML content into BivvyConfig.
///
/// # Arguments
///
/// * `content` - The YAML content to parse
/// * `source_path` - Path for error reporting
pub fn parse_config(content: &str, source_path: &Path) -> Result<BivvyConfig> {
    serde_yaml::from_str(content).map_err(|e| BivvyError::ConfigParseError {
        path: source_path.to_path_buf(),
        message: e.to_string(),
    })
}

/// Load a config file as raw YAML Value (for merging).
///
/// Returns the raw serde_yaml::Value without deserializing into
/// BivvyConfig, which allows for deep merging before final parsing.
pub fn load_config_value(path: &Path) -> Result<serde_yaml::Value> {
    let content = fs::read_to_string(path).map_err(|e| {
        if e.kind() == std::io::ErrorKind::NotFound {
            BivvyError::ConfigNotFound {
                path: path.to_path_buf(),
            }
        } else {
            BivvyError::Io(e)
        }
    })?;

    serde_yaml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
        path: path.to_path_buf(),
        message: e.to_string(),
    })
}

/// Load split-file definitions and return a synthetic YAML value.
///
/// Reads each file in `paths`, wraps its content under `top_key.<stem>`,
/// and merges them all into one value. For example, `.bivvy/steps/database.yml`
/// becomes `{ steps: { database: <file content> } }`.
///
/// # Errors
///
/// Returns `ConfigParseError` if any file cannot be read or parsed.
fn load_split_files(paths: &[PathBuf], top_key: &str) -> Result<Option<serde_yaml::Value>> {
    if paths.is_empty() {
        return Ok(None);
    }

    let mut entries = serde_yaml::Mapping::new();

    for path in paths {
        let stem = path.file_stem().and_then(|s| s.to_str()).ok_or_else(|| {
            BivvyError::ConfigParseError {
                path: path.clone(),
                message: "Could not determine name from filename".to_string(),
            }
        })?;

        let value = load_config_value(path)?;

        entries.insert(serde_yaml::Value::String(stem.to_string()), value);
    }

    let mut wrapper = serde_yaml::Mapping::new();
    wrapper.insert(
        serde_yaml::Value::String(top_key.to_string()),
        serde_yaml::Value::Mapping(entries),
    );

    Ok(Some(serde_yaml::Value::Mapping(wrapper)))
}

/// Parse a single workflow file into a [`WorkflowFile`], auto-detecting
/// new vs. legacy format.
///
/// New format: file has a top-level `workflow:` mapping. The whole file
/// is parsed as `WorkflowFile`.
///
/// Legacy format: no top-level `workflow:` key. The file is parsed as
/// `WorkflowConfig` and wrapped in a `WorkflowFile` with empty
/// `steps`/`vars`, preserving the workflow declaration as-is.
pub fn parse_workflow_file_value(
    value: serde_yaml::Value,
    source_path: &Path,
) -> Result<WorkflowFile> {
    let is_new_format = value
        .as_mapping()
        .map(|m| m.contains_key(serde_yaml::Value::String("workflow".to_string())))
        .unwrap_or(false);

    if is_new_format {
        serde_yaml::from_value(value).map_err(|e| BivvyError::ConfigParseError {
            path: source_path.to_path_buf(),
            message: e.to_string(),
        })
    } else {
        let workflow: WorkflowConfig =
            serde_yaml::from_value(value).map_err(|e| BivvyError::ConfigParseError {
                path: source_path.to_path_buf(),
                message: e.to_string(),
            })?;
        Ok(WorkflowFile {
            description: workflow.description.clone(),
            steps: Default::default(),
            vars: Default::default(),
            workflow,
        })
    }
}

/// Read a workflow file from disk and parse it into a [`WorkflowFile`].
///
/// This is the public entry point used by `bivvy lint --workflow <name>`
/// and discovery-based commands that want a single workflow file in
/// isolation, without merging anything else.
pub fn load_single_workflow_file(path: &Path) -> Result<WorkflowFile> {
    let value = load_config_value(path)?;
    parse_workflow_file_value(value, path)
}

/// Read a step file from disk and parse it into a [`StepConfig`].
///
/// Step files are simpler than workflow files — they have only one shape.
pub fn load_single_step_file(path: &Path) -> Result<StepConfig> {
    let content = fs::read_to_string(path).map_err(|e| {
        if e.kind() == std::io::ErrorKind::NotFound {
            BivvyError::ConfigNotFound {
                path: path.to_path_buf(),
            }
        } else {
            BivvyError::Io(e)
        }
    })?;
    serde_yaml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
        path: path.to_path_buf(),
        message: e.to_string(),
    })
}

/// Convert a [`WorkflowFile`] into the partial `BivvyConfig` YAML value it
/// contributes to the merge chain.
///
/// Produces a mapping with `vars`, `steps`, and `workflows.<stem>` keys.
/// The workflow's description falls back to the file-level description
/// when not set inside the `workflow:` block.
fn workflow_file_to_partial(file: &WorkflowFile, stem: &str) -> Result<serde_yaml::Value> {
    let mut wrapper = serde_yaml::Mapping::new();

    if !file.vars.is_empty() {
        let vars_value =
            serde_yaml::to_value(&file.vars).map_err(|e| BivvyError::ConfigParseError {
                path: PathBuf::from(format!(".bivvy/workflows/{stem}.yml")),
                message: format!("Failed to serialize workflow vars: {e}"),
            })?;
        wrapper.insert(serde_yaml::Value::String("vars".to_string()), vars_value);
    }

    if !file.steps.is_empty() {
        let steps_value =
            serde_yaml::to_value(&file.steps).map_err(|e| BivvyError::ConfigParseError {
                path: PathBuf::from(format!(".bivvy/workflows/{stem}.yml")),
                message: format!("Failed to serialize workflow steps: {e}"),
            })?;
        wrapper.insert(serde_yaml::Value::String("steps".to_string()), steps_value);
    }

    let mut workflow = file.workflow.clone();
    if workflow.description.is_none() {
        if let Some(ref desc) = file.description {
            workflow.description = Some(desc.clone());
        }
    }

    let workflow_value =
        serde_yaml::to_value(&workflow).map_err(|e| BivvyError::ConfigParseError {
            path: PathBuf::from(format!(".bivvy/workflows/{stem}.yml")),
            message: format!("Failed to serialize workflow: {e}"),
        })?;

    let mut workflows_map = serde_yaml::Mapping::new();
    workflows_map.insert(serde_yaml::Value::String(stem.to_string()), workflow_value);
    wrapper.insert(
        serde_yaml::Value::String("workflows".to_string()),
        serde_yaml::Value::Mapping(workflows_map),
    );

    Ok(serde_yaml::Value::Mapping(wrapper))
}

/// Load every workflow file in `paths`, parse each as `WorkflowFile`
/// (with legacy fallback), and produce one merged partial config value.
fn load_split_workflow_files_all(paths: &[PathBuf]) -> Result<Option<serde_yaml::Value>> {
    if paths.is_empty() {
        return Ok(None);
    }

    let partials: Vec<serde_yaml::Value> = paths
        .iter()
        .map(|path| {
            let stem = path.file_stem().and_then(|s| s.to_str()).ok_or_else(|| {
                BivvyError::ConfigParseError {
                    path: path.clone(),
                    message: "Could not determine name from filename".to_string(),
                }
            })?;
            let file = load_single_workflow_file(path)?;
            workflow_file_to_partial(&file, stem)
        })
        .collect::<Result<Vec<_>>>()?;

    Ok(Some(merge_configs(&partials)))
}

/// Collect config values in merge order, including split files.
///
/// Merge order:
/// 1. Remote base configs (from `extends:`)
/// 2. User global config (`~/.bivvy/config.yml`)
/// 3. Project config (`.bivvy/config.yml`)
/// 4. Split-file steps (`.bivvy/steps/*.yml`)
/// 5. Split-file workflows (`.bivvy/workflows/*.yml`) — selection
///    determines which files participate.
/// 6. Local overrides (`.bivvy/config.local.yml`)
fn collect_config_values(
    paths: &ConfigPaths,
    workflows: WorkflowSelection<'_>,
) -> Result<Vec<serde_yaml::Value>> {
    let mut configs = Vec::new();

    // 1. Remote extends (populated later by resolver)
    for p in &paths.extends {
        configs.push(load_config_value(p)?);
    }

    // 2. User global
    if let Some(p) = &paths.user_global {
        configs.push(load_config_value(p)?);
    }

    // 3. Project config
    if let Some(p) = &paths.project {
        configs.push(load_config_value(p)?);
    }

    // 4. Split-file steps
    if let Some(v) = load_split_files(&paths.split_steps, "steps")? {
        configs.push(v);
    }

    // 5. Split-file workflows (selected per request)
    match workflows {
        WorkflowSelection::All => {
            if let Some(v) = load_split_workflow_files_all(&paths.split_workflows)? {
                configs.push(v);
            }
        }
        WorkflowSelection::One(name) => {
            if let Some(path) = paths.split_workflows.iter().find(|p| {
                p.file_stem()
                    .and_then(|s| s.to_str())
                    .is_some_and(|stem| stem == name)
            }) {
                let file = load_single_workflow_file(path)?;
                configs.push(workflow_file_to_partial(&file, name)?);
            }
        }
        WorkflowSelection::None => {}
    }

    // 6. Local overrides
    if let Some(p) = &paths.project_local {
        configs.push(load_config_value(p)?);
    }

    Ok(configs)
}

/// Load and merge all config files for a project.
///
/// Discovers and merges configs in this order:
/// 1. Remote base configs (from `extends:`)
/// 2. User global config (`~/.bivvy/config.yml`)
/// 3. Project config (`.bivvy/config.yml`)
/// 4. Split-file steps (`.bivvy/steps/*.yml`)
/// 5. Split-file workflows (`.bivvy/workflows/*.yml`)
/// 6. Local overrides (`.bivvy/config.local.yml`)
///
/// # Errors
///
/// Returns `ConfigNotFound` if no project config exists.
/// Returns `ConfigParseError` if any config file is invalid.
pub fn load_merged_config(project_root: &Path) -> Result<BivvyConfig> {
    load_merged_config_with_resolver(project_root, &ExtendsResolver::default())
}

/// Load and merge configs with a specific extends resolver.
///
/// This is the implementation behind `load_merged_config`, exposed
/// separately to allow injecting a custom resolver for testing.
pub fn load_merged_config_with_resolver(
    project_root: &Path,
    resolver: &ExtendsResolver,
) -> Result<BivvyConfig> {
    let paths = ConfigPaths::discover(project_root);

    if !paths.has_project_config() {
        return Err(BivvyError::ConfigNotFound {
            path: project_root.join(".bivvy").join("config.yml"),
        });
    }

    let configs = collect_config_values(&paths, WorkflowSelection::All)?;

    // Merge all configs
    let merged = merge_configs(&configs);

    // Parse merged value into typed config
    let config: BivvyConfig =
        serde_yaml::from_value(merged).map_err(|e| BivvyError::ConfigParseError {
            path: project_root.join(".bivvy").join("config.yml"),
            message: format!("Failed to parse merged config: {}", e),
        })?;

    // Migrate deprecated fields (watches → change checks, etc.)
    let mut config = config;
    config.migrate_deprecated_fields();

    // Resolve extends if present
    if config.extends.is_some() {
        let resolved = resolver.resolve(&config)?;
        Ok(resolved)
    } else {
        Ok(config)
    }
}

/// Load and merge configs with trust verification for remote extends URLs.
///
/// This is the full-featured config loader that verifies trust for remote
/// extends URLs. The `trust_policy` determines behavior for untrusted URLs:
/// - `TrustAll`: auto-trusts (--trust flag)
/// - `Prompt`: asks the user via UI (interactive mode)
/// - `Reject`: errors on untrusted URLs (non-interactive mode)
///
/// Trusted URLs are persisted so they don't need to be re-approved.
pub fn load_merged_config_with_trust(
    project_root: &Path,
    resolver: &ExtendsResolver,
    trust_policy: TrustPolicy,
    trust_store_path: &Path,
    ui: &mut dyn Prompter,
) -> Result<BivvyConfig> {
    let paths = ConfigPaths::discover(project_root);

    if !paths.has_project_config() {
        return Err(BivvyError::ConfigNotFound {
            path: project_root.join(".bivvy").join("config.yml"),
        });
    }

    let configs = collect_config_values(&paths, WorkflowSelection::All)?;

    let merged = merge_configs(&configs);

    let mut config: BivvyConfig =
        serde_yaml::from_value(merged).map_err(|e| BivvyError::ConfigParseError {
            path: project_root.join(".bivvy").join("config.yml"),
            message: format!("Failed to parse merged config: {}", e),
        })?;

    // Migrate deprecated fields (watches → change checks, etc.)
    config.migrate_deprecated_fields();

    if config.extends.is_some() {
        let mut trust_store = TrustStore::load(trust_store_path).map_err(BivvyError::Other)?;
        let mut store_modified = false;

        let resolved = resolver
            .resolve_with_trust(&config, &mut |url: &str| {
                if trust_store.is_trusted(url) {
                    return Ok(());
                }

                match trust_policy {
                    TrustPolicy::TrustAll => {
                        trust_store.trust(url);
                        store_modified = true;
                        Ok(())
                    }
                    TrustPolicy::Reject => Err(anyhow::anyhow!(
                        "Untrusted remote config URL: {}. Use --trust to auto-approve or run interactively to confirm.",
                        url
                    )),
                    TrustPolicy::Prompt => {
                        let prompt = Prompt {
                            key: format!("trust_url_{}", url),
                            question: format!(
                                "Trust remote config from {}? (y/N)",
                                url
                            ),
                            prompt_type: PromptType::Confirm,
                            default: Some("false".to_string()),
                        };

                        match ui.prompt(&prompt) {
                            Ok(PromptResult::Bool(true)) => {
                                trust_store.trust(url);
                                store_modified = true;
                                Ok(())
                            }
                            _ => Err(anyhow::anyhow!(
                                "Untrusted remote config URL rejected by user: {}",
                                url
                            )),
                        }
                    }
                }
            })
            .map_err(BivvyError::Other)?;

        if store_modified {
            trust_store
                .save(trust_store_path)
                .map_err(BivvyError::Other)?;
        }

        Ok(resolved)
    } else {
        Ok(config)
    }
}

/// Load config with optional path override.
///
/// If `config_override` is provided, loads only that file without merging.
/// Otherwise, discovers and merges all config files.
pub fn load_config(project_root: &Path, config_override: Option<&Path>) -> Result<BivvyConfig> {
    if let Some(override_path) = config_override {
        // Direct load of specified file, no merging
        load_config_file(override_path)
    } else {
        load_merged_config(project_root)
    }
}

/// Load only `.bivvy/config.yml`, with no merging of other files.
///
/// This is the cheap path used by commands that only operate on the
/// project file (like `bivvy add`). It does not consult `~/.bivvy/`,
/// split-file directories, or `config.local.yml`. Returns an empty
/// `BivvyConfig` when the file does not exist (callers can detect this
/// via [`Discovery::project_config_path`] if needed).
pub fn load_project_config(project_root: &Path) -> Result<BivvyConfig> {
    let discovery = Discovery::new(project_root);
    match discovery.project_config_path() {
        Some(path) => load_config_file(&path),
        None => Err(BivvyError::ConfigNotFound {
            path: project_root.join(".bivvy").join("config.yml"),
        }),
    }
}

/// Full deep-merge load path, but only the named workflow file
/// participates in the chain.
///
/// This is the loader used by `bivvy run <workflow>`. It walks the
/// resolution chain (extends → user-global → project → split steps →
/// the named workflow file → local) and produces a final
/// [`BivvyConfig`]. Other workflow files are not parsed, so a malformed
/// sibling cannot break a run of an unrelated workflow.
pub fn load_for_run(project_root: &Path, workflow_name: &str) -> Result<BivvyConfig> {
    load_for_run_with_resolver(project_root, workflow_name, &ExtendsResolver::default())
}

/// Variant of [`load_for_run`] that accepts a custom extends resolver.
///
/// Exposed for tests that inject a mocked HTTP server.
pub fn load_for_run_with_resolver(
    project_root: &Path,
    workflow_name: &str,
    resolver: &ExtendsResolver,
) -> Result<BivvyConfig> {
    let paths = ConfigPaths::discover(project_root);

    if !paths.has_project_config() {
        return Err(BivvyError::ConfigNotFound {
            path: project_root.join(".bivvy").join("config.yml"),
        });
    }

    let configs = collect_config_values(&paths, WorkflowSelection::One(workflow_name))?;
    let merged = merge_configs(&configs);

    let mut config: BivvyConfig =
        serde_yaml::from_value(merged).map_err(|e| BivvyError::ConfigParseError {
            path: project_root.join(".bivvy").join("config.yml"),
            message: format!("Failed to parse merged config: {}", e),
        })?;

    config.migrate_deprecated_fields();

    if config.extends.is_some() {
        let resolved = resolver.resolve(&config)?;
        Ok(resolved)
    } else {
        Ok(config)
    }
}

/// Variant of [`load_for_run`] with trust verification for remote `extends:` URLs.
///
/// This is the production loader for `bivvy run`. Behavior is identical
/// to [`load_merged_config_with_trust`] except that only the named
/// workflow file participates in the merge chain.
pub fn load_for_run_with_trust(
    project_root: &Path,
    workflow_name: &str,
    resolver: &ExtendsResolver,
    trust_policy: TrustPolicy,
    trust_store_path: &Path,
    ui: &mut dyn Prompter,
) -> Result<BivvyConfig> {
    let paths = ConfigPaths::discover(project_root);

    if !paths.has_project_config() {
        return Err(BivvyError::ConfigNotFound {
            path: project_root.join(".bivvy").join("config.yml"),
        });
    }

    let configs = collect_config_values(&paths, WorkflowSelection::One(workflow_name))?;
    let merged = merge_configs(&configs);

    let mut config: BivvyConfig =
        serde_yaml::from_value(merged).map_err(|e| BivvyError::ConfigParseError {
            path: project_root.join(".bivvy").join("config.yml"),
            message: format!("Failed to parse merged config: {}", e),
        })?;

    config.migrate_deprecated_fields();

    if config.extends.is_some() {
        let mut trust_store = TrustStore::load(trust_store_path).map_err(BivvyError::Other)?;
        let mut store_modified = false;

        let resolved = resolver
            .resolve_with_trust(&config, &mut |url: &str| {
                if trust_store.is_trusted(url) {
                    return Ok(());
                }

                match trust_policy {
                    TrustPolicy::TrustAll => {
                        trust_store.trust(url);
                        store_modified = true;
                        Ok(())
                    }
                    TrustPolicy::Reject => Err(anyhow::anyhow!(
                        "Untrusted remote config URL: {}. Use --trust to auto-approve or run interactively to confirm.",
                        url
                    )),
                    TrustPolicy::Prompt => {
                        let prompt = Prompt {
                            key: format!("trust_url_{}", url),
                            question: format!(
                                "Trust remote config from {}? (y/N)",
                                url
                            ),
                            prompt_type: PromptType::Confirm,
                            default: Some("false".to_string()),
                        };

                        match ui.prompt(&prompt) {
                            Ok(PromptResult::Bool(true)) => {
                                trust_store.trust(url);
                                store_modified = true;
                                Ok(())
                            }
                            _ => Err(anyhow::anyhow!(
                                "Untrusted remote config URL rejected by user: {}",
                                url
                            )),
                        }
                    }
                }
            })
            .map_err(BivvyError::Other)?;

        if store_modified {
            trust_store
                .save(trust_store_path)
                .map_err(BivvyError::Other)?;
        }

        Ok(resolved)
    } else {
        Ok(config)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
